```dts
/include/ "system-conf.dtsi"

/ {
	chosen {
		bootargs = "earlycon console=ttyPS0,115200 clk_ignore_unused root=/dev/mmcblk1p2 rw rootwait";
		stdout-path = "serial0:115200n8";
	};

	reserved-memory {
		#address-cells = <2>;
		#size-cells = <2>;
		ranges;

		rproc@3ed000000 {
			no-map;
			reg = <0x0 0x3ed00000 0x0 0x1000000>;
		};
	};

	amba {
		vring@0 {
			compatible = "vring_uio";
			reg = <0x0 0x3ed40000 0x0 0x40000>;
		};

		shm@0 {
			compatible = "shm_uio";
			reg = <0x0 0x3ed80000 0x0 0x100000>;
		};

		iio@ff340000 {
			compatible = "iio_uio";
			reg = <0x0 0xff340000 0x0 0x1000>;
			interrupt-parent = <&gic>;
			interrupts = <0 29 4>;
		};
	};
};

/* ===== 网口核心配置（千兆 SFP） ===== */
&gem3 {
	status = "okay";
	phy-mode = "sgmii";
	phy-handle = <&phyc>;

	phyc: phy@c {
		reg = <0x0c>;
		ti,rx-internal-delay = <0x08>;
		ti,tx-internal-delay = <0x0a>;
		ti,fifo-depth = <0x01>;
		ti,rxctrl-strap-worka;
	};

	fixed-link {
		speed = <1000>;
		full-duplex;
	};
};

/* ===== PL 端 UIO 驱动挂载 ===== */
&axi_bram_ctrl_0 {
	compatible = "generic-uio";
	status = "okay";
};

&usp_rf_data_converter_0 {
	compatible = "xlnx,usp-rf-data-converter-2.6";
	uio-name = "uio4";
	uio-offset = <0x40000>;
	interrupts = <0 89 4>;
};
```

