import serial
import time

def main():
    try:
        s = serial.Serial('COM12', 115200, timeout=1)
    except Exception as e:
        print(f"Error opening COM12: {e}")
        return

    # Check incoming
    time.sleep(0.5)
    in_bytes = s.in_waiting
    print(f"Bytes in buffer before write: {in_bytes}")
    if in_bytes:
        print("Buffer content:", repr(s.read(in_bytes)))

    # Try sending multiple returns
    for i in range(3):
        s.write(b'\r\n')
        time.sleep(0.5)
        if s.in_waiting:
            print(f"Response after enter {i+1}:", repr(s.read(s.in_waiting)))

    s.close()

if __name__ == '__main__':
    main()

